async function loadController(name){let source=await readFile(new URL('./'+name+'.js',import.meta.url),'utf8');source=source.replace("import './workSales.css';",'');for(const file of ['isolatedOperationCopyModel.mjs','workCopyPresentation.mjs','workCopyPresentation.mjs','currencyAccountPresentation.mjs','workTradeModel.mjs','workCatalogModel.mjs','workCatalogPhoto.mjs','testCustomersModel.mjs','workFinanceMovements.mjs'])source=source.replace("'./"+file+"'",JSON.stringify(new URL('./'+file,import.meta.url).href));return import('data:text/javascript;base64,'+Buffer.from(source).toString('base64'));}
function dom(){const nodes=new Map();const node=k=>{if(!nodes.has(k))nodes.set(k,{isConnected:true,innerHTML:'',textContent:'',dataset:{},elements:{search:{value:''}},setAttribute(name,value){this[name]=value;},remove(){this.removed=true;const field=/^\[data-(sale|collection)-preview-result\]$/.exec(k);if(field)root.innerHTML=root.innerHTML.replace(new RegExp('<div class="trade-preview" data-'+field[1]+'-preview-result>[\\s\\S]*?</button></div>'),'');},addEventListener(event,fn){this['on'+event]=fn;},querySelector:node,querySelectorAll:()=>[]});return nodes.get(k);};const root={isConnected:true,innerHTML:'',querySelector:node,querySelectorAll(selector){const field=selector.slice(1,-1),key=field.slice(5).replace(/-([a-z])/g,(_,c)=>c.toUpperCase()),re=new RegExp(field+'="([^"]+)"','g');return [...root.innerHTML.matchAll(re)].map(m=>{const n=node(selector+m[1]);n.dataset[key]=m[1];return n;});}};return {root,node};}
